import{_ as a,C as r,o as s,c as o,E as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"A Healthy Service Does Not Mean the Task May Continue: An OpenHands Liveness Failure and Agent Recovery Boundaries","description":"","frontmatter":{"title":"A Healthy Service Does Not Mean the Task May Continue: An OpenHands Liveness Failure and Agent Recovery Boundaries","date":"2026-08-26","column":"digital-employee","category":"daily","article_type":"case-study","edition":"research-center","research_question":"When the service still responds and a session or execution attempt still exists, how can the runtime prove that the task remains eligible to continue and that downstream release is causally justified by satisfied prerequisites?","summary":"From an OpenHands incident where health stayed green while a conversation lost liveness to a real CodeFlowMu recovery chain, this study separates service health, execution liveness, task eligibility, causal prerequisites, and formal acceptance.","sources":"Public primary sources and the bounded scope of access-controlled first-party evidence are listed in the article.","project_relevance":"case-evidence","item_id":"EBR-20260826-04","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-26-service-health-task-recovery-case-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-26-service-health-task-recovery-case.md","filePath":"en/digital-employee/2026-08-26-service-health-task-recovery-case.md","lastUpdated":1787803935000}'),l={name:"en/digital-employee/2026-08-26-service-health-task-recovery-case.md"};function c(d,e,h,u,p,v){const t=r("ArticleCover");return s(),o("div",null,[i(t,{image:"/assets/covers/daily-2026-08-26-service-health-task-recovery-case-cover.png",kicker:"Digital Employee · Engineering Research",title:"A Healthy Service Does Not Mean the Task May Continue: An OpenHands Liveness Failure and Agent Recovery Boundaries",summary:"Health only says the service still answers. Real recovery has to re-prove task eligibility, prerequisite satisfaction, and the evidence behind every release.",version:"EBR-20260826-04",status:"Engineering Research · 2026-08-26",languageHref:"/zh/digital-employee/2026-08-26-service-health-task-recovery-case",languageLabel:"中文"}),e[0]||(e[0]=n('<h1 id="a-healthy-service-does-not-mean-the-task-may-continue-an-openhands-liveness-failure-and-agent-recovery-boundaries" tabindex="-1">A Healthy Service Does Not Mean the Task May Continue: An OpenHands Liveness Failure and Agent Recovery Boundaries <a class="header-anchor" href="#a-healthy-service-does-not-mean-the-task-may-continue-an-openhands-liveness-failure-and-agent-recovery-boundaries" aria-label="Permalink to &quot;A Healthy Service Does Not Mean the Task May Continue: An OpenHands Liveness Failure and Agent Recovery Boundaries&quot;">​</a></h1><p><strong>A 200 response proves only that some endpoint still answers. It does not prove that the session is making progress, and it certainly does not prove that the current task is still eligible to continue. Reliable agent recovery has to re-establish who is authorized to recover, whether the task is in a legal executable state, whether the current execution right is still valid, and whether the upstream facts required for downstream release are actually satisfied.</strong></p><p>CodeFlowMu is a locally run multi-agent collaboration system that uses tasks, roles, gates, reports, and approvals to organize agent work into an execution chain that can be traced, recovered, and verified. We preserved one real recovery record from 2026-08-25. It did not become a tidy “the system self-healed” story, because the record contains a more valuable discrepancy: <strong>QA&#39;s physical release timestamp precedes the two upstream terminal-report timestamps.</strong></p><p>That does not prove the gate was bypassed. It also does not allow us to claim that the dependency was proven satisfied. It exposes a different problem: <strong>timestamp order is not causal proof.</strong></p><h2 id="_1-one-green-light-cannot-answer-five-questions" tabindex="-1">1. One green light cannot answer five questions <a class="header-anchor" href="#_1-one-green-light-cannot-answer-five-questions" aria-label="Permalink to &quot;1. One green light cannot answer five questions&quot;">​</a></h2><p>During an agent-system fault, several distinct facts are often flattened into a single healthy/unhealthy state. At minimum, five layers should be separated:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it actually answers</th><th>What it cannot substitute for</th></tr></thead><tbody><tr><td>Service health</td><td>Does the process or API respond?</td><td>Whether the session is progressing</td></tr><tr><td>Execution liveness</td><td>Is the current session / job still advancing?</td><td>Whether the task is eligible to continue</td></tr><tr><td>Task eligibility</td><td>Is the task uniquely projected, legal, and dispatchable now?</td><td>Whether upstream prerequisites are satisfied</td></tr><tr><td>Causal prerequisite</td><td>Why may this downstream item be released now?</td><td>Whether the business result is accepted</td></tr><tr><td>Formal acceptance</td><td>Has an authorized role accepted the delivery?</td><td>The technical facts above</td></tr></tbody></table><p>A recovery chain should therefore not be:</p><p><strong>service is up → wake the agent again</strong></p><p>It should look more like:</p><p><strong>authorize recovery → reconcile attempt and task state → prove prerequisites → dispatch again → verify evidence → formal acceptance</strong></p><p>No layer should sign for another.</p><h2 id="_2-openhands-provides-the-lower-layer-comparison-health-can-stay-green-while-a-conversation-loses-liveness" tabindex="-1">2. OpenHands provides the lower-layer comparison: health can stay green while a conversation loses liveness <a class="header-anchor" href="#_2-openhands-provides-the-lower-layer-comparison-health-can-stay-green-while-a-conversation-loses-liveness" aria-label="Permalink to &quot;2. OpenHands provides the lower-layer comparison: health can stay green while a conversation loses liveness&quot;">​</a></h2><p>OpenHands software-agent-sdk PR #4548 records a concrete production incident. A browser-tool conversation shutdown remained stuck for roughly <strong>8 hours and 21 minutes</strong> while <code>/health</code> and metadata routes still returned 200. Conversation event requests, however, could not be opened normally. At the service layer the system looked alive; at the specific conversation layer it was no longer making useful progress.</p><p>The failure centered on <code>AsyncExecutor.close()</code>: remaining tasks were not cancelled, and the portal-thread wait was unbounded. The repair cancels remaining work and adds a default <strong>10-second</strong> bound to shutdown waiting. If the timeout expires, the code warns and abandons the infinite wait. The PR is explicit that this is a <strong>bounded, best-effort safety net</strong>, not proof that every resource has been cleaned up.</p><p>That distinction matters:</p><blockquote><p><strong>Bounded shutdown limits blast radius; it does not certify clean completion.</strong></p></blockquote><p>The OpenHands case supports one narrow external conclusion: <strong>service health ≠ session liveness.</strong> It is not CodeFlowMu&#39;s root cause and does not validate our task-recovery model.</p><h2 id="_3-codeflowmu-s-fault-was-higher-in-the-stack-the-worker-could-be-woken-before-the-task-was-legally-active" tabindex="-1">3. CodeFlowMu&#39;s fault was higher in the stack: the worker could be woken before the task was legally active <a class="header-anchor" href="#_3-codeflowmu-s-fault-was-higher-in-the-stack-the-worker-could-be-woken-before-the-task-was-legally-active" aria-label="Permalink to &quot;3. CodeFlowMu&#39;s fault was higher in the stack: the worker could be woken before the task was legally active&quot;">​</a></h2><p>The CodeFlowMu failure was not a shutdown hang. A recovery path could wake a worker before the task completed the lifecycle transition required for execution.</p><p>This kind of fault is deceptively easy to “fix” operationally: if the agent is stalled, dispatch it again. But if the task has not moved correctly from an inbox-like state into active execution, another wake simply propagates inconsistency downstream. A new Session, report, test run, or eventual done state may all rest on an invalid task premise.</p><p>The ADMIN recovery directive therefore bounded PM&#39;s authority: repair lifecycle transition, wake-up, and report-gate behavior; add regression evidence; recover or redispatch two stalled work items; and <strong>do not release QA until genuine DEV and OPS terminal reports exist</strong>. This was not a general takeover privilege. It was recovery authority scoped to a named fault and named actions.</p><p>That makes the first recovery question a governance question:</p><blockquote><p><strong>Who is authorized to repair this path, and how far does that authority extend?</strong></p></blockquote><h2 id="_4-the-most-valuable-part-of-the-timeline-is-what-it-does-not-prove" tabindex="-1">4. The most valuable part of the timeline is what it does not prove <a class="header-anchor" href="#_4-the-most-valuable-part-of-the-timeline-is-what-it-does-not-prove" aria-label="Permalink to &quot;4. The most valuable part of the timeline is what it does not prove&quot;">​</a></h2><p>The public A4 timeline preserves these key points:</p><table tabindex="0"><thead><tr><th>Beijing time</th><th>Event</th></tr></thead><tbody><tr><td>14:35:22</td><td>bounded recovery directive became effective</td></tr><tr><td>14:35:29</td><td>recovery context reached PM</td></tr><tr><td>14:43:54</td><td>OPS recovery dispatch recorded</td></tr><tr><td>14:47:32</td><td>DEV recovery dispatch recorded</td></tr><tr><td>14:48:25</td><td>QA moved from inbox to active</td></tr><tr><td>14:48:42</td><td>OPS terminal report submitted</td></tr><tr><td>14:49:37</td><td>DEV terminal report submitted</td></tr><tr><td>15:30:36</td><td>active-before-wake repair committed and grouped verification completed</td></tr></tbody></table><p>By physical time, QA became active 17 seconds before the OPS terminal report and 72 seconds before the DEV terminal report. The recovery directive, however, required those terminal reports before QA release.</p><p>There are two equally bad overclaims one could make from this record.</p><p>The first is:</p><blockquote><p>QA was definitely released in violation of the gate.</p></blockquote><p>The public evidence is not strong enough for that conclusion. Write time, logical event time, clock source, or an omitted precursor event may differ.</p><p>The second is:</p><blockquote><p>Because OPS, DEV, and QA all reached terminal states later, the prerequisite order has been proven correct.</p></blockquote><p>There is no evidence for that either.</p><p>The record supports a narrower statement:</p><blockquote><p><strong>The causal basis for QA release is not bound clearly enough in the published record to prove the prerequisite was satisfied at release time.</strong></p></blockquote><p>That is a more useful result than a polished recovery success story, because it tells us exactly what the next evidence layer must add.</p><h2 id="_5-why-wall-clock-timestamps-cannot-carry-prerequisite-proof-by-themselves" tabindex="-1">5. Why wall-clock timestamps cannot carry prerequisite proof by themselves <a class="header-anchor" href="#_5-why-wall-clock-timestamps-cannot-carry-prerequisite-proof-by-themselves" aria-label="Permalink to &quot;5. Why wall-clock timestamps cannot carry prerequisite proof by themselves&quot;">​</a></h2><p>In distributed or multi-process agent systems, physical time is excellent for diagnosis but is not automatically a causal credential. We may have action time, event-emission time, persistence time, API-response time, and different process clocks.</p><p>Therefore even if:</p><p><strong>A.time &lt; B.time</strong></p><p>we still cannot automatically conclude:</p><p><strong>A is a satisfied prerequisite of B.</strong></p><p>A checkable release should instead look closer to:</p><p><strong>QA release → prerequisites: OPS_REPORT#... + DEV_REPORT#... → required task revision → logical sequence / version precondition</strong></p><p>The release record itself should say what facts made continuation legal. Wall-clock time should remain for troubleshooting, but it should not be the sole proof of causality.</p><p>That is the difference between an ordinary log and a prerequisite proof. A log tells us what happened around the same time. A prerequisite proof tells us why this action was eligible to happen then.</p><h2 id="_6-the-repair-tightened-activate-before-wake-not-declare-the-business-task-successful" tabindex="-1">6. The repair tightened “activate before wake,” not “declare the business task successful” <a class="header-anchor" href="#_6-the-repair-tightened-activate-before-wake-not-declare-the-business-task-successful" aria-label="Permalink to &quot;6. The repair tightened “activate before wake,” not “declare the business task successful”&quot;">​</a></h2><p>The Runtime repair did not try to adjudicate business success. It strengthened the mechanical prerequisites for dispatch:</p><ul><li>lifecycle activation must succeed before a worker can start;</li><li>activation failure is fail-closed: no TASK_BOUND Session starts and no active lease remains;</li><li>the current attempt, execution right, and responsible agent must still match;</li><li>YAML / file fallback paths cannot bypass lifecycle checks;</li><li>PM recovery requests enter through a stable recovery skill and routing path instead of turning fault detection into unlimited repair authority.</li></ul><p>The repair verification is kept as separate groups: lifecycle governance <strong>16 / 16</strong>, task dispatch <strong>46 / 46</strong>, YAML fallback <strong>4 / 4</strong>, PM core / routing <strong>7 / 7</strong>, and recovery-skill routing <strong>5 / 5</strong>. Together these are 78 grouped assertions, with Runtime TypeScript type checking reporting no errors.</p><p>Those results support a bounded claim: <strong>the named active-before-wake repair paths passed their corresponding regressions.</strong> They do not prove that every Runtime fault is automatically recoverable, and they do not retroactively create causal evidence for the historical QA release.</p><h2 id="_7-what-should-a-stronger-recovery-contract-look-like" tabindex="-1">7. What should a stronger recovery contract look like? <a class="header-anchor" href="#_7-what-should-a-stronger-recovery-contract-look-like" aria-label="Permalink to &quot;7. What should a stronger recovery contract look like?&quot;">​</a></h2><p>Abstracting from this incident, a high-risk recovery should pass through a chain like:</p><p><strong>recovery authority → attempt / lease reconciliation → lifecycle activation → prerequisite binding → worker wake → execution evidence → formal acceptance</strong></p><p>Each layer has a different job:</p><ul><li>health proves only that the service can answer;</li><li>heartbeat / progress signals prove only execution liveness;</li><li>lifecycle activation proves that the task may enter execution;</li><li>prerequisite binding proves why the downstream item may be released now;</li><li>REPORT / test output creates delivery evidence;</li><li>REVIEW / ADMIN produces the formal business conclusion.</li></ul><p>The goal of recovery is therefore not to wake more agents faster. It is to make every continuation answer:</p><blockquote><p><strong>Who authorized this recovery? Why is the current task eligible to execute now? Which upstream facts satisfy its prerequisites? Which revision do those facts belong to? Who later accepted the resulting delivery?</strong></p></blockquote><h2 id="conclusion-recovery-is-not-restart-it-is-re-establishing-eligibility" tabindex="-1">Conclusion: recovery is not restart; it is re-establishing eligibility <a class="header-anchor" href="#conclusion-recovery-is-not-restart-it-is-re-establishing-eligibility" aria-label="Permalink to &quot;Conclusion: recovery is not restart; it is re-establishing eligibility&quot;">​</a></h2><p>The OpenHands incident reminds us that <strong>health cannot sign for liveness</strong>. The CodeFlowMu recovery case adds that <strong>liveness cannot sign for task eligibility or prerequisite satisfaction</strong>.</p><p>A reliable agent runtime should keep “still answers,” “still running,” “may continue,” “prerequisites satisfied,” and “accepted for delivery” as separate facts connected by explicit evidence relationships.</p><p>This case does not end with a perfect all-clear. Instead, it preserves a useful gap: QA&#39;s physical release timestamp precedes two upstream report timestamps, and the current evidence is insufficient to prove the causal order either way.</p><p>That is what engineering evidence should do. It should not invent a cleaner story than the record supports. It should show what still needs to be made checkable.</p><blockquote><p><strong>A healthy service does not mean the task may continue. Recovery must re-prove why continuation is legal now.</strong></p></blockquote><hr><h2 id="public-evidence" tabindex="-1">Public evidence <a class="header-anchor" href="#public-evidence" aria-label="Permalink to &quot;Public evidence&quot;">​</a></h2><ul><li><a href="/joinwell52/evidence/execution-boundary-20260826/v2/case-a4-recovery-timeline.csv"><strong>A4 authorization, recovery, and verification timeline (CSV)</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/transcript-a4.md" target="_blank" rel="noreferrer"><strong>A4 sanitized audit and regression transcript (GitHub)</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/claim-evidence-map.csv" target="_blank" rel="noreferrer"><strong>Claim-to-evidence map (GitHub)</strong></a></li><li><a href="/joinwell52/zh/digital-employee/2026-08-26-execution-boundary-evidence-data"><strong>Public, sanitized four-case Execution Boundary evidence note</strong></a></li></ul><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><h3 id="openhands" tabindex="-1">OpenHands <a class="header-anchor" href="#openhands" aria-label="Permalink to &quot;OpenHands&quot;">​</a></h3><ul><li><a href="https://github.com/OpenHands/software-agent-sdk/pull/4548" target="_blank" rel="noreferrer"><strong>OpenHands software-agent-sdk PR #4548 — bound <code>AsyncExecutor.close()</code></strong></a>, merged 2026-08-25. This article uses the source-reported incident in which health / metadata still answered while conversation shutdown and event access lost liveness, plus the repair that cancels remaining work, bounds close waiting to ten seconds by default, and treats timeout abandonment as best-effort rather than guaranteed cleanup. The 8h21m incident was not independently reproduced here.</li></ul><p>The OpenHands case is used only for <strong>service health ≠ session liveness</strong>. It is not presented as CodeFlowMu&#39;s root cause or as an equivalent recovery model.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>The CodeFlowMu claims are limited to the named 2026-08-25 bounded recovery case and the paths covered by the public A4 evidence. The record supports that recovery authority had a defined scope; controlled recovery occurred; the lifecycle, dispatch, fallback, PM routing, and recovery-skill regression groups passed; and QA&#39;s physical release timestamp precedes the two upstream terminal-report timestamps.</p><p>This evidence <strong>does not prove</strong> that QA definitely violated its gate, nor does it prove that the causal prerequisite was satisfied. It also does not establish that all Runtime faults are recoverable through the same path. Full Sessions, agent transcripts, conversations, and local-machine paths are not public.</p><p>Conclusions should be read together with the corresponding version, test sets, and evidence boundary.</p>',77))])}const y=a(l,[["render",c]]);export{m as __pageData,y as default};
